const usd=n=>Number.isFinite(n)?(n>0?'+':n<0?'-':'')+'$'+Math.abs(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}):'—';
const fmt=(n,d=1)=>Number.isFinite(n)?n.toFixed(d):'—',signed=(n,d=0)=>Number.isFinite(n)?(n>0?'+':'')+n.toFixed(d):'—';
