 if(!r){metric(metrics,'TIME DIFFERENCE','—','Compare both options');metric(metrics,'MONEY DIFFERENCE','—','Only entered costs count');metric(metrics,'EFFORT DIFFERENCE','—','Your self-rated workload');add(target,'p',kind==='prep'?$('prepResult').textContent||'Define success and preparation minutes. Learned chances appear after enough checked outcomes.':'Enter your options and calculate to see what drives the score.','dash-empty');return;}
 const violations=r.violations?.length||r.alternativeViolations?.length||r.limits?.length||r.alternativeLimits?.length||r.boundary||r.blocked;if(violations){const warning=add(target,'p',r.boundary?'Their refusal overrides every score.':r.verdict||'A stated limit or boundary is exceeded. Revise the plan.','dash-warning');target.insertBefore(warning,metrics);}
